+
+function commands(world: World) {
+    return world[$internal].deferred.scopes.flat();
+}
+
+function pending(world: World, entity: Entity) {
+    return commands(world).some((command) => command.entity === entity);
+}
+
+/** Flush before an immediate entity mutation so command order remains intuitive. */
+export function flushDeferredFor(entity: Entity) {
+    const world = getEntityWorld(entity);
+    const ctx = world[$internal];
+    if (!ctx.isFlushingDeferred && pending(world, entity)) flushDeferred(world);
+}
+
+function isDestroyed(world: World, entity: Entity) {
+    return commands(world).some((command) => command.entity === entity && command.type === 'destroy');
+}
+
+function configsHave(configs: ConfigurableTrait[], trait: Trait | RelationPair) {
+    return configs.some((config) => {
+        if (isRelationPair(trait)) return isRelationPair(config) && config === trait;
+        if (isRelationPair(config)) return false;
+        return Array.isArray(config) ? config[0] === trait : config === trait;
+    });
+}
+
+export function hasDeferred(world: World, entity: Entity, trait: Trait | RelationPair): boolean {
+    if (!pending(world, entity)) return isRelationPair(trait) ? hasRelationPair(world, entity, trait) : hasTrait(world, entity, trait);
+    let result = isRelationPair(trait) ? hasRelationPair(world, entity, trait) : hasTrait(world, entity, trait as Trait);
+    for (const command of commands(world)) {
+        if (command.entity !== entity) continue;
+        if (command.type === 'destroy') return false;
+        if (command.type === 'spawn' || command.type === 'add' || command.type === 'addExclusive') {
+            if (command.type === 'addExclusive' && isRelationPair(trait) && configsHave(command.traits, trait)) result = true;
+            else if (configsHave(command.traits, trait)) result = true;
+        } else if (command.type === 'remove' && configsHave(command.traits as ConfigurableTrait[], trait)) result = false;
+        if (isRelationPair(trait) && command.type === 'addExclusive') {
+            for (const config of command.traits) {
+                if (isRelationPair(config) && config[$internal].relation === trait[$internal].relation) {
+                    result = config[$internal].target !== '*' && config === trait;
+                }
+            }
+        }
+    }
+    return result;
+}
+
+export function getDeferred(world: World, entity: Entity, trait: Trait | RelationPair) {
+    if (!hasDeferred(world, entity, trait)) return undefined;
+    let value = getTrait(world, entity, trait);
+    for (const command of commands(world)) {
+        if (command.entity !== entity || !('traits' in command)) continue;
+        for (const config of command.traits as ConfigurableTrait[]) {
+            if (isRelationPair(trait)) {
+                if (config === trait && isRelationPair(config)) value = config[$internal].params;
+            } else if (!isRelationPair(config) && (Array.isArray(config) ? config[0] : config) === trait) {
+                value = Array.isArray(config) ? config[1] : value;
+            }
+        }
+    }
+    return value;
+}
+
+function addReplacing(world: World, entity: Entity, config: ConfigurableTrait) {
+    if (isRelationPair(config)) {
+        addTrait(world, entity, config);
+        return;
+    }
+    const trait = Array.isArray(config) ? config[0] : config;
+    const value = Array.isArray(config) ? config[1] : undefined;
+    if (hasTrait(world, entity, trait)) {
+        if (value !== undefined) setTrait(world, entity, trait, value);
+    } else addTrait(world, entity, config);
+}
+
+function execute(world: World, command: DeferredCommand) {
+    const ctx = world[$internal];
+    if (command.type === 'spawn') {
+        if (isDestroyed(world, command.entity)) {
+            releaseEntity(ctx.entityIndex, command.entity);
+            ctx.entityTraits.delete(command.entity);
+            return;
+        }
+        // The id was reserved when queued; initialise it without allocating another id.
+        for (const query of ctx.notQueries) {
+            const match = query.check(world, command.entity);
+            if (match) query.add(command.entity);
+        }
+        ctx.entityTraits.set(command.entity, new Set());
+        for (const trait of command.traits) addReplacing(world, command.entity, trait);
+        return;
+    }
+    if (command.entity === ctx.worldEntity && command.type === 'destroy') {
+        throw new Error('Koota: The world entity cannot be destroyed by a deferred command.');
+    }
+    if (!world.has(command.entity)) return;
+    if (command.type === 'destroy') return destroyEntity(world, command.entity);
+    if (command.type === 'remove') return removeTrait(world, command.entity, ...command.traits);
