+}
+
+export function flushDeferred(world: World) {
+    const ctx = world[$internal];
+    const scope = ctx.deferred.scopes.at(-1)!;
+    if (!scope.length) return;
+    // Remove the scope first: execution must not see its own destroy commands as pending.
+    ctx.deferred.scopes[ctx.deferred.scopes.length - 1] = [];
