+        for (const command of scope) execute(world, command);
+    } finally {
+        ctx.isFlushingDeferred = false;
+    }
+}
+
+export function createDeferred(world: World): DeferredWorld {
+    const queue = (command: DeferredCommand) => world[$internal].deferred.scopes.at(-1)!.push(command);
+    return {
+        spawn(...traits) {
+            const entity = allocateEntity(world[$internal].entityIndex);
+            queue({ type: 'spawn', entity, traits });
+            return entity;
+        },
+        destroy(entity) { queue({ type: 'destroy', entity }); },
+        add(entity, ...traits) { queue({ type: 'add', entity, traits }); },
+        remove(entity, ...traits) { queue({ type: 'remove', entity, traits }); },
+        addExclusive(entity, ...traits) { queue({ type: 'addExclusive', entity, traits }); },
+        flush() { flushDeferred(world); },
+    };
+}
+
+export function enterDeferredScope(world: World) { world[$internal].deferred.scopes.push([]); }
+export function exitDeferredScope(world: World) {
+    flushDeferred(world);
+    world[$internal].deferred.scopes.pop();
+}
